insert into pajang_private.question_catalog(id,prompt,samples) values
  (3, '설레는 사람과 김밥을 싼다면 어떤 재료를 서로 바꿔 넣어 보고 싶나요?', array['저는 아삭한 오이를 두 줄 넣어요.', '볶은 묵은지를 길게 깔래요.', '도톰한 달걀말이가 제 주인공이에요.']),
  (7, '첫 데이트가 빵집이라면 어떤 빵을 둘이 나눠 먹고 싶나요?', array['소금빵 양 끝을 하나씩 잡아요.', '따끈한 단팥빵을 반으로 가를래요.', '길쭉한 바게트를 손으로 뜯어요.']),
  (15, '처음 만난 두 사람 모두 메뉴를 못 고를 때, 어떻게 제안할까요?', array['각자 궁금한 걸 하나씩 짚어 봐요.', '직원에게 인기 메뉴 두 가지를 물어요.', '못 먹는 음식부터 슬쩍 물어봐요.']),
  (22, '좋아하는 사람과 첫 바비큐를 한다면, 무엇부터 구워 건넬까요?', array['통마늘을 포일에 싸서 구울래요.', '가래떡을 노릇하게 굽고 꿀을 꺼내요.', '가지에 칼집을 내고 된장을 발라요.']),
  (26, '상대가 내 밥상에 처음 앉는다면 어떤 반찬부터 맛보라고 할까요?', array['들기름에 구운 두부요.', '새콤하게 무친 오이 한 점이요.', '반숙으로 조린 간장 달걀이요.']),
  (32, '둘이 가는 첫 소풍, 뚜껑을 열면 상대가 웃을 도시락 한 칸은요?', array['토끼 모양으로 깎은 사과요.', '작은 유부초밥을 빼곡히 채워요.', '이쑤시개로 집어 먹는 방울토마토요.']),
  (39, '부침개를 둘이 부치다 손이 겹치면 어떻게 역할을 나누고 싶나요?', array['뒤집을 때만큼은 제가 나설게요.', '바삭한 가장자리를 집어 주는 담당이요.', '곁들일 간장을 새콤하게 만들어요.']),
  (46, '편의점에서 짧게 만난 사이, 어떤 조합을 추천하며 말을 걸까요?', array['컵수프에 삼각김밥을 말아요.', '바닐라 아이스크림 위에 에스프레소요.', '고구마를 갈라 스트링치즈를 넣어요.']),
  (49, '귤 한 상자를 받아 좋아하는 사람이 생각났어요. 어떻게 나누고 싶나요?', array['큰 것 작은 것 섞어 종이봉투에 담아요.', '귤잼 두 병을 만들어 하나 건네요.', '귤 껍질에 웃는 얼굴을 그려 줘요.']),
  (58, '함께 요리하는 사람이 서툴러 미안해하면 어떤 말을 해 줄까요?', array['저도 첫 팬케이크는 항상 찢어져요.', '옆에 서서 맛만 봐줘도 좋아요.', '천천히 해요. 급한 건 하나도 없어요.']),
  (62, '첫 식사 후 조금 더 이야기하고 싶을 때 어떤 디저트를 제안할까요?', array['쌉싸래한 티라미수에 숟가락 두 개요.', '팥빙수 하나에 떡을 더 얹어요.', '따뜻한 사과파이를 나눠 먹어요.']),
  (68, '분식집에서 취향이 통했다고 느끼는 건 어떤 순간일까요?', array['같은 순간 김말이를 국물에 찍을 때요.', '둘 다 달걀을 맨 마지막에 남길 때요.', '말없이 순한 맛에 함께 동그라미 칠 때요.']),
  (73, '마음에 든 사람이 커피를 안 마신다면 다음 만남을 어디로 잡을까요?', array['꽃차 향을 고르는 작은 찻집이요.', '디저트와 과일 음료가 있는 카페요.', '테이크아웃 주스 들고 공원 벤치로요.']),
  (81, '두 사람만의 단골 식당이 생긴다면 어떤 자리에 자주 앉고 싶나요?', array['서로 표정이 잘 보이는 창가 자리요.', '조리하는 손이 보이는 나란한 바 자리요.', '얘기가 편하게 오가는 조용한 구석이요.']),
  (86, '입맛이 없다고 말한 날, 좋아하는 사람이 뭘 해 주면 고마울까요?', array['조금만 먹고 남겨도 된다고 해 줘요.', '먹고 싶은 게 생기면 말해 달래요.', '따뜻한 국물을 앞접시에 덜어 줘요.']),
  (94, '서로 토스트 한 장씩 만들어 주기로 했어요. 내 조합을 소개한다면요?', array['무가당 땅콩버터 위에 딸기잼 조금이요.', '마요네즈를 바르고 김가루를 뿌려요.', '무화과가 씹히는 크림치즈요.']),
  (102, '포장 음식을 기다리는 십 분, 썸 타는 사람과 뭘 하고 싶나요?', array['근처 가게 구경을 한 바퀴 해요.', '포장 음식을 먹으며 틀 노래를 골라요.', '주문한 메뉴의 맛을 서로 상상해요.']),
  (104, '내가 끓인 국수를 건네기 전, 상대에게 마지막으로 묻고 싶은 건요?', array['고춧가루 좀 더 넣을까요?', '구운 김이랑 달걀 중에 뭐 올릴까요?', '국물은 넉넉한 게 좋아요?']),
  (114, '다음 데이트 요리를 고르며 함께 요리책을 펼쳤어요. 어디서 멈출까요?', array['완성 사진보다 손동작 사진이 많은 쪽이요.', '냉장고 재료로 바로 할 수 있는 요리요.', '그 요리에 얽힌 이야기로 시작하는 쪽이요.']),
  (119, '나란히 만두 빚는 데이트, 내가 만든 건 뭘 보고 알아볼 수 있을까요?', array['속이 통통해서 간신히 닫힐 거예요.', '주름을 하나씩 잡아 반달로 빚어요.', '동그랗게 말아서 끝을 붙여요.']),
  (121, '좋아하는 사람이 출출해할 때 남은 밥 한 공기로 해 주고 싶은 건요?', array['팬에 꾹 눌러 누룽지를 만들어요.', '잘게 썬 김치랑 고슬고슬 볶아요.', '김에 싸서 한입 주먹밥으로 만들어요.']),
  (127, '데이트 상대가 만든 음식을 맛봤다면 어떤 칭찬을 먼저 건네나요?', array['국물에서 볶은 파 향이 나서 좋다고 해요.', '이거랑 밥 한 그릇은 금방이겠다고 해요.', '이 버섯은 어떻게 이렇게 구웠냐고 물어요.']),
  (136, '둘이 장터에 간다면, 장바구니에 가장 먼저 같이 담고 싶은 건요?', array['나눠 먹을 만두 한 봉지요.', '함께 구울 버섯을 고를래요.', '맛이 궁금한 작은 병잼이요.']),
  (141, '첫 냉면 데이트에서 주문하기 전에 살짝 맞춰 보고 싶은 건요?', array['물과 비빔을 하나씩 시켜 한입씩 바꿔요.', '가위가 필요한지 먼저 물어봐요.', '만두 한 접시도 나눌지 의논해요.']),
  (145, '아침 데이트에 먼저 도착했다면 기다리는 시간을 어떻게 쓰나요?', array['같은 자리에 햇빛이 얼마나 드나 봐요.', '주문은 기다렸다 하고 메뉴판만 봐요.', '오는 길에 보일 간판 사진을 보내요.']),
  (154, '길거리 어묵을 함께 먹다가 마음이 따뜻해지는 순간은요?', array['제 국물이 식으면 새로 따라 줄 때요.', '먼저 먹으라고 자리 한쪽을 내줄 때요.', '추운지도 잊고 둘 다 한 꼬치 더 고를 때요.']),
  (157, '연인과 서로의 집 카레 맛을 소개한다면 내 쪽 재료는 뭘까요?', array['덩어리째 푹 익힌 감자요.', '갈색이 날 때까지 볶은 양파요.', '살짝 달큰하게 볶아 넣는 사과요.']),
  (163, '마음에 드는 사람과의 저녁 식사에 어떤 음악이 어울릴까요?', array['숟가락 소리랑 어울리는 잔잔한 재즈요.', '낮 식당에는 경쾌한 기타 연주요.', '밥 먹으며 흥얼거릴 옛날 가요요.']),
  (172, '시장 데이트에서 번갈아 한 입씩 사 주기로 했다면 뭘 고를까요?', array['처음 보는 나물 무침 한 젓가락이요.', '낯선 과일을 한 조각 잘라 먹어요.', '수제 어묵집의 제일 색다른 맛이요.']),
  (176, '첫 저녁 약속을 잡을 때 상대가 해 주면 반가운 질문은요?', array['점심에 이미 먹은 메뉴가 있어요?', '이야기하기 편한 조용한 곳 좋아해요?', '먹고 싶은 것과 피하고 싶은 게 있나요?']),
  (183, '내 단골 식당에 좋아하는 사람을 처음 데려간다면 뭘 알려 줄까요?', array['메뉴판엔 작게 적힌 제일 맛있는 요리요.', '볕이 덜 들어 느긋하게 앉을 수 있는 자리요.', '사장님이 늘 챙겨 주는 따뜻한 숭늉이요.']),
  (188, '둘이 처음 라면을 끓일 때 꼭 미리 맞춰 볼 취향은 뭔가요?', array['면을 얼마나 꼬들하게 남길지요.', '달걀을 풀지 통째로 둘지요.', '물을 넉넉히 넣을지 진하게 먹을지요.']),
  (194, '첫 데이트가 끝나고도 상대가 떠오를 아이스크림 맛을 지어 본다면요?', array['둘이 나눈 팝콘을 닮은 소금 캐러멜이요.', '복숭아 홍차 마신 날이라 복숭아 셔벗이요.', '같이 고른 라테가 떠오르는 커피우유 맛이요.']),
  (199, '내가 좋아하는 음식을 상대는 안 좋아한다면 어떻게 함께 먹을까요?', array['그 재료는 따로 담아 제 몫에만 넣어요.', '둘 다 좋아하는 다른 메뉴를 찾아요.', '먹어 보고 싶다 할 때만 한 점 건네요.']),
  (207, '조용한 식당에서 말이 잠깐 끊겼을 때 어떻게 다시 말을 걸까요?', array['방금 제일 맛있던 게 뭔지 물어봐요.', '오는 길에 본 웃긴 간판 얘기를 꺼내요.', '급히 채우지 않고 미소부터 건네요.']),
  (213, '비 때문에 야외 데이트가 취소됐어요. 대신 둘이 만들고 싶은 건요?', array['대파 듬뿍 넣은 수제비요.', '우유를 데워 만든 따끈한 코코아요.', '남은 김치로 손바닥만 한 전을 부쳐요.']),
  (221, '연인이 내 음식을 먹기 전에 소스를 듬뿍 뿌리면 어떻게 할까요?', array['다음엔 소스를 작은 그릇에 따로 담아요.', '같은 소스 찍어 한입 바꿔 먹어 봐요.', '어떤 소스를 제일 좋아하는지 물어요.']),
  (226, '딸기가 좋은 날, 딸기를 핑계로 어떤 데이트를 제안할까요?', array['절반은 으깨고 절반은 썰어 딸기우유요.', '식빵 사이에 생크림과 딸기를 끼워요.', '요거트 위에 산처럼 쌓고 나눠요.']),
  (231, '우리 첫 식사를 사진 한 장으로만 남긴다면 어떤 장면을 담을까요?', array['첫 조각을 자르는 손을 담아요.', '상 가득 모인 접시를 위에서 찍어요.', '다 먹고 남은 마지막 감자 하나요.']),
  (235, '영화 데이트에서 상대가 편하게 먹을 간식을 고르는 내 기준은요?', array['한 입에 쏙 들어가는 크기요.', '씹으면 소리가 날 만큼 바삭한지요.', '손에 가루가 덜 묻는지도 중요해요.']),
  (244, '둘만의 아침 메뉴 이름을 하나 지어 본다면 무엇인가요?', array['눈 뜨면 반가운 달걀 두 개요.', '오 분만 더 누워 있는 토스트요.', '사과 반쪽씩 나누는 아침이요.']),
  (250, '빵 한 개를 같이 먹을 때 상대가 내게 양보해 줬으면 하는 부분은요?', array['바게트라면 단단한 꼬투리요.', '식빵 가운데 폭신한 쪽이 좋아요.', '견과류가 밖으로 톡 나온 조각이요.']),
  (255, '작은 식탁에 좋아하는 사람을 초대한 날, 미리 준비해 두는 건요?', array['손 닿는 곳에 물잔을 채워 놔요.', '좋아한다고 했던 반찬을 하나 더 해요.', '서로 얼굴이 잘 보이게 꽃병을 옮겨요.']),
  (261, '데이트 가는 길에 떡집에 들렀어요. 나눌 간식으로 무엇을 고를까요?', array['콩가루가 수북한 인절미요.', '깨가 톡 터지는 작은 송편이요.', '구름처럼 폭신한 백설기요.']),
  (266, '함께 전골을 다 먹고 눈이 마주쳤어요. 어떤 마무리를 제안할까요?', array['남은 국물에 칼국수를 넣어요.', '김가루 섞은 볶음밥으로 눌러요.', '마지막 국물만 한 숟갈 더 먹어요.']),
  (275, '입맛이 다른 사람과 요리를 정할 때 내게 가장 편한 방식은요?', array['두 사람 다 먹는 재료부터 적어 봐요.', '오늘은 제 취향, 다음엔 상대 취향으로요.', '양념을 나중에 각자 고르는 메뉴로요.']),
  (281, '식당에서 상대의 어떤 작은 행동이 눈에 들어오나요?', array['뜨거운 접시가 닿지 않게 자리를 내줘요.', '주문 받아 준 분께 눈 맞춰 인사해요.', '물컵을 채우기 전에 더 마실지 물어요.']),
  (288, '상대가 해 준 요리가 맛있어서 다음에 같이 만들어 보고 싶다면요?', array['양파 볶는 냄새 좋던데 저도 배워도 돼요?', '다음엔 제가 재료를 사 올까요?', '같이 만들고 레시피에 둘 이름을 쓸까요?']),
  (290, '산책 중에 잠시 앉아 나눠 먹기 좋은 간식은 뭘까요?', array['손에 묻지 않는 한입 주먹밥이요.', '앉은자리에서 나눌 귤 두 개요.', '한 조각씩 떼어 먹는 초콜릿이요.']),
  (300, '다음에 만난 사람이 어떤 사소한 식성을 기억해 주면 설렐까요?', array['깍두기 국물을 좋아하는 거요.', '고수를 조금 더 얹어 먹는 거요.', '따뜻한 차를 식사 뒤에 마시는 거요.']),
  (303, '상대가 데이트 장소를 예약해 뒀다면 어떤 방식으로 고마움을 전할까요?', array['덕분에 편하게 왔다고 먼저 말해요.', '다음에 좋아할 만한 곳은 제가 찾아요.', '식사 끝나고 잘 어울리는 차를 사요.']),
  (312, '피자 취향이 정반대인 둘이라면 첫 주문을 어떻게 맞출까요?', array['각자 고른 맛을 반반으로 해요.', '토핑은 따로 받아 반쪽씩 얹어요.', '작은 피자 둘로 골라 한 조각씩 바꿔요.']),
  (318, '데이트 중에 같이 만든 요리가 실패하면 어떤 반응이 편할까요?', array['모양은 망했지만 일단 같이 맛봐요.', '이 요리에 새 이름을 붙이고 웃어요.', '정리하고 맛있는 걸 먹으러 나가요.']),
  (322, '연인과 타는 첫 밤 기차, 둘이 조용히 나눌 간식을 챙긴다면요?', array['부드러운 카스텔라와 우유요.', '한 알씩 먹기 편한 청포도요.', '작게 잘라 온 꿀고구마요.']),
  (328, '단것을 안 좋아한다는 상대의 말을 기억해 뒀다면 어떤 선물을 고를까요?', array['향 좋은 김 한 묶음이요.', '그날 짠 들기름 작은 병이요.', '바삭하게 구운 현미 누룽지요.']),
  (332, '그 계절이 오면 좋아하는 사람과 꼭 먹고 싶은 한 끼는 무엇인가요?', array['달래장 비빔밥을 먹으면 봄 같아요.', '첫 찰옥수수를 먹으면 여름이에요.', '붕어빵 팥이 뜨거우면 겨울이 온 거죠.']),
  (342, '둘이 만든 샌드위치 중 어느 게 누구 것인지 표시하는 방법은요?', array['서로 다른 색 종이로 반씩 포장해요.', '각자 좋아하는 모양으로 잘라요.', '종이띠에 별명 한 글자씩 써요.']),
  (346, '연인과 같이 담가 두고 다음 만남에 열어 보고 싶은 음식은요?', array['하룻밤 두고 먹는 오이피클이요.', '제철 레몬으로 만드는 레몬청이요.', '잘 익혀 수제비에 곁들일 열무김치요.']),
  (353, '아직 어색한 둘이 자연스럽게 손을 움직이며 먹을 메뉴는 뭘까요?', array['재료를 각자 넣는 월남쌈이요.', '뒤집는 순간 같이 보는 큰 해물파전이요.', '취향대로 담아 끓이는 샤부샤부요.']),
  (355, '둘이 쓰는 식탁을 ‘우리 자리’답게 바꾸고 싶다면 어떤 무늬를 고를까요?', array['보리차랑 잘 어울리는 파란 체크요.', '그릇이 돋보이는 무늬 없는 연두색이요.', '레몬이 띄엄띄엄 그려진 천이요.']),
  (361, '중식당 데이트에서 둘이 한 접시를 나눈다면 무엇을 주문할까요?', array['소리가 경쾌한 누룽지탕이요.', '가지가 사르르 풀리는 지삼선이요.', '새우를 꽉 채운 멘보샤요.']),
  (367, '주말 브런치 데이트를 내가 준비한다면 무엇을 식탁 가운데 놓을까요?', array['토마토소스에 달걀을 익힌 팬 하나요.', '오이랑 햄을 넣은 작은 모닝빵이요.', '폭신한 팬케이크와 새콤한 베리요.']),
  (377, '좋아하는 사람에게 내 마음을 과일 하나로 건넨다면 어떻게 줄까요?', array['잘 익은 복숭아를 골라 종이에 감싸요.', '수박을 한입 크기로 썰어 포크와 건네요.', '귤 하나에 웃는 얼굴을 그려 줘요.']),
  (380, '둘이 차린 첫 밥상 사진에 어떤 제목을 붙이고 싶나요?', array['냉장고 탐험대의 비빔밥이요.', '불 하나로 완성한 저녁이요.', '한 숟갈 더 먹고 가는 상이요.']),
  (385, '추운 날 만난 상대와 수프를 나눠 먹고 싶을 때 무엇을 곁들일까요?', array['끝이 바삭한 마늘빵이요.', '후추를 바로 갈아 넣는 작은 그라인더요.', '큼직한 머그잔에 담긴 따뜻한 물이요.']),
  (394, '중요한 일을 앞둔 연인에게 음식으로 응원을 보낸다면요?', array['먹기 편하게 작게 썬 과일이요.', '긴 하루 끝에 데워 먹을 곰국이요.', '잘 풀리길 바라며 돌돌 만 소면이요.']),
  (397, '둘이 여행하다 휴게소에 잠깐 섰어요. 어느 간식부터 먹자고 할까요?', array['갓 볶은 알감자 냄새를 따라가요.', '따끈한 호두과자를 작은 봉지로 사요.', '후루룩 먹고 오는 우동 코너요.']),
  (403, '매운맛을 잘 먹는 정도가 다른 두 사람, 어떤 주문이면 편할까요?', array['국물은 순하게, 고추는 옆에 따로요.', '맑은 탕과 얼큰한 볶음을 하나씩요.', '메뉴를 고르기 전에 맛보기부터 해요.']),
  (413, '둘이 빵 반죽이 부풀기를 기다리며 함께하고 싶은 일은요?', array['밀가루 묻은 조리대를 닦아요.', '빵을 찍어 먹을 올리브유를 담아요.', '다 구워지면 들을 노래를 골라요.']),
  (419, '상대가 골라 온 채소와 내가 고른 채소로 어떤 한 끼를 차릴까요?', array['애호박, 감자, 양파로 된장찌개요.', '오이, 당근, 깻잎을 썰어 냉채요.', '파프리카, 버섯, 단호박을 구워요.']),
  (426, '첫 만남에서 취향 이야기를 꺼낸다면 어떤 질문으로 시작할까요?', array['쫄깃한 빵이랑 바삭한 빵 중 뭐 좋아해요?', '탕수육 소스는 어디에 두면 좋을까요?', '메뉴 고를 때 식감이랑 향 중 뭐가 먼저예요?']),
  (432, '연인과 한 팀이 되어 해 보고 싶은 엉뚱한 주방 실험은요?', array['같은 원두에 물 온도만 바꿔 커피를 내려요.', '감자를 써는 두께만 바꿔 구워요.', '달걀 삶는 시간을 일 분씩 달리해요.']),
  (437, '둘 다 늦잠 잔 주말, 느지막한 점심 데이트를 뭘로 시작할까요?', array['잔멸치 주먹밥에 따끈한 국물이요.', '두툼한 프렌치토스트 두 조각이요.', '과일 듬뿍 넣은 차가운 시리얼이요.']),
  (440, '서로 상대 취향대로 요구르트를 꾸며 준다면 내 그릇엔 뭘 부탁할까요?', array['볶은 메밀을 조금 뿌려요.', '꿀에 재운 호두 두 알이요.', '시나몬 향 나는 그래놀라요.']),
  (449, '영화 보며 연인과 과자 봉지를 열 때 슬쩍 건네받고 싶은 조각은요?', array['가장 진하게 구워진 누룽지 칩이요.', '서로 붙어서 두툼해진 감자칩이요.', '초콜릿이 가장 많이 박힌 쿠키요.']),
  (456, '연인이 한 숟갈 더 달라고 하면 제일 뿌듯할 내 요리는 무엇인가요?', array['양파를 오래 볶아 만든 수프요.', '콩을 불려 직접 끓인 비지찌개요.', '들깨를 갈아 넣은 버섯볶음이요.']),
  (462, '데이트 상대와 처음 장을 볼 때 자연스럽게 대화가 트이는 코너는요?', array['빵 코너에서 각자 단골 빵 이야기를 해요.', '과일 앞에서 제일 좋아하는 계절을 물어요.', '면 코너에서 야식 짝꿍을 추천해요.']),
  (465, '데이트 후 헤어지기 아쉬울 때 차 한 잔과 어떤 과자를 더 주문할까요?', array['생강 향 진한 얇은 쿠키요.', '매작과 한 조각을 천천히 먹어요.', '볶은 콩이 박힌 담백한 전병이요.']),
  (469, '상대가 자꾸 내 접시에 음식을 덜어 줄 때 편하게 취향을 말한다면요?', array['고마워요, 이번 건 제가 조금만 덜게요.', '이 버섯 진짜 좋아해요, 그거 하나만요.', '남겨 두면 얘기하면서 천천히 먹을게요.']),
  (480, '데이트할 때 손으로 뜯어 먹으며 격식 없이 나누고 싶은 음식은요?', array['겹이 결대로 찢어지는 우유식빵이요.', '갓 찐 감자 껍질을 벗겨 먹어요.', '짭짤한 먹태를 가늘게 뜯어요.']),
  (484, '첫 데이트 식당에 대기가 길다면 상대와 어떻게 결정하고 싶나요?', array['근처를 걸으며 천천히 기다려요.', '다음에 일찍 오기로 하고 옆집에 가요.', '간단한 전채를 먹고 다시 와요.']),
  (489, '데이트 제안을 받았을 때 어떤 식당 설명을 들으면 마음이 움직이나요?', array['목소리를 높이지 않아도 얘기가 들린대요.', '제가 궁금해한 요리를 잘하는 집이래요.', '근처에 같이 걷기 좋은 길이 있대요.']),
  (498, '서로에게 주는 쿠키를 굽는다면 어떤 모양에 마음을 담을까요?', array['손잡이가 작은 찻잔 모양이요.', '두 개를 맞추면 한 쌍이 되는 퍼즐이요.', '틀 없이 숟가락으로 툭툭 떠 놔요.']),
  (500, '좋아하는 사람이 내 입맛에 맞춰 찌개를 끓여 준다면 무엇을 부탁할까요?', array['두부를 큼직하게 떠먹는 게 좋아요.', '애호박이 푹 익어 국물이 달면 좋아요.', '된장을 진하게 풀어 밥에 비벼요.']),
  (505, '상대와 식사를 나누다 취향이 꼭 같지 않아 다행이라고 느끼는 순간은요?', array['저는 피자 끝을, 상대는 가운데를 좋아해요.', '상대가 제가 남긴 올리브를 반겨요.', '먹어 본 적 없는 반찬을 추천받아요.']),
  (515, '좋아하는 사람이 찾아오는 날, 문을 열 때 풍겼으면 하는 향은요?', array['갓 지은 버섯밥의 구수한 김이요.', '채소가 푹 익은 토마토 스튜 향이요.', '갓 쪄 낸 옥수수의 달큰한 냄새요.']),
  (520, '함께 차린 식사 뒤 상대가 설거지를 시작하면 나는 무엇을 맡을까요?', array['마른행주로 그릇을 닦아 제자리에 둬요.', '남은 반찬을 작은 통에 옮겨요.', '식탁을 닦고 식후 차를 우려요.']),
  (526, '초밥 데이트에서 상대가 기억해 줬으면 하는 나만의 마지막 한 점은요?', array['달콤하고 폭신한 달걀초밥이요.', '새우의 탱글탱글한 식감으로 끝내요.', '가볍게 먹는 새콤한 유부초밥이요.']),
  (529, '만나는 사람이 평소 물을 잘 안 마신다면 어떤 물 한 잔을 권할까요?', array['오이 한 조각을 얇게 띄워요.', '민트 잎을 손뼉으로 살짝 쳐 넣어요.', '동그란 얼음 하나를 천천히 녹여요.']),
  (540, '처음 같이 요리한 날 상대에게서 뜻밖에 배우고 싶은 건 뭔가요?', array['자투리 채소까지 맛있게 볶는 법이요.', '작은 부엌에서도 서로 비켜 주는 요령이요.', '간 볼 때 망설이지 않고 의견을 내는 법이요.']),
  (546, '어릴 때 좋아한 간식을 서로 하나씩 소개한다면 내 이야기는 뭔가요?', array['발라 먹느라 오래 걸린 옥수수요.', '입천장에 붙던 얇은 호박엿이요.', '분홍색 종이에 싸인 네모난 빵이요.']),
  (548, '추위 타는 연인을 식탁에 맞이하기 전 가장 먼저 데워 둘 것은요?', array['국물을 담을 두툼한 사발이요.', '찐 고구마를 담아 둔 작은 냄비요.', '손에 쥐고 있을 생강차 한 잔이요.']),
  (558, '둘이 신청하는 빵 수업이라면 함께 익히고 싶은 기술은 뭐예요?', array['반죽이 충분히 부푼 순간을 알고 싶어요.', '크루아상에 얇은 결을 내는 법이요.', '케이크에 생크림을 반듯하게 바르는 법이요.']),
  (564, '데이트 중 서로 주문하지 못한 메뉴가 아쉬우면 어떻게 풀까요?', array['처음부터 빈 접시 두 장을 부탁해요.', '각자 한입 먹고 작은 그릇으로 나눠요.', '다음에 반대로 주문하자고 약속해요.']),
  (569, '더위에 지친 상대에게 시원한 한 그릇을 해 준다면 어떤 맛일까요?', array['오이냉국의 새큼한 식초 맛이요.', '콩국수의 고소하고 묵직한 맛이요.', '동치미의 맑고 알싸한 끝맛이요.']),
  (571, '다음 만남을 제안할 때 감자 세 알을 귀여운 핑계로 삼는다면요?', array['감자전 세 장 나올 텐데 한 장 드실래요?', '감자샐러드 만들어서 소풍 갈까요?', '따뜻한 감자수프 해 볼 건데 같이 맛봐요.']),
  (579, '수저를 내려놓고도 생각나는 건 함께한 식사의 어떤 순간일까요?', array['바닥에 붙은 누룽지를 나눠 긁을 때요.', '빈 접시를 보고 둘 다 웃던 순간이요.', '나가면서 주방 쪽에 잘 먹었다고 할 때요.']),
  (585, '같이 장을 보다가 예정에 없던 재료에 눈이 갔을 때 어떻게 제안할까요?', array['이 깻잎 향 좀 맡아 봐요, 쌈 어때요?', '면 모양이 재밌는데 둘이 반씩 써 볼래요?', '잘 익은 무화과 하나씩 먹고 갈래요?']),
  (593, '연인의 친구들과 첫 식사 자리에 직접 만들어 가고 싶은 건요?', array['덜어 먹기 편한 잡채 큰 그릇이요.', '하나씩 집어 갈 미니 약과요.', '각자 싸 먹을 수 있는 쌈 채소요.']),
  (596, '팬케이크 데이트에서 상대에게 줄 한 장에 어떤 속을 숨기고 싶나요?', array['잘 익은 바나나를 얇게 잘라요.', '새콤한 블루베리 조림 한 숟갈이요.', '설탕 없이 휘핑한 생크림이요.']),
  (603, '여행 가는 연인이 먹거리 선물을 골라 준다면 무엇을 부탁할까요?', array['그 지역 마트에서만 보는 과자요.', '작은 병에 든 동네 꿀이요.', '거기 사람들이 밥에 뿌리는 양념이요.']),
  (608, '좋아하는 사람에게 처음 대접할 자신 있는 집밥 한 그릇은요?', array['간장을 눈대중으로 넣는 어묵탕이요.', '남은 반찬으로 만드는 계란볶음밥이요.', '눈짐작으로 말아도 딱 맞는 김밥이요.']),
  (613, '주말에 따뜻한 점심을 해 주겠다는 사람에게 어떤 면을 부탁할까요?', array['바지락 듬뿍 넣은 칼국수요.', '레몬 향 살짝 나는 오일 파스타요.', '들기름에 가볍게 버무린 메밀면이요.']),
  (623, '둘의 접시에 딸기 한 알만 남았다면 어떻게 나누고 싶나요?', array['반으로 썰어 각자 케이크에 올려요.', '누가 더 얇게 자르나 내기해요.', '으깨서 분홍 우유 한 잔씩 나눠요.']),
  (630, '연인이 볶음밥을 덜어 줄 때 어떤 한 술을 담아 주면 반가울까요?', array['아래쪽에 눌어붙은 바삭한 밥이요.', '가운데 얹힌 반숙 노른자부터요.', '채소가 알록달록 섞인 한 술이요.']),
  (634, '식사 뒤 계산대 앞에서 덜 어색하려면 어떤 말이 편한가요?', array['반씩 나누면 저는 편한데 어떠세요?', '오늘은 제가 초대했으니 제가 살게요.', '이건 고맙게 먹고 차는 제가 살게요.']),
  (641, '마음에 드는 사람이 추천한 음식이 낯설면 어떻게 첫 입을 맛볼까요?', array['소스를 찍기 전에 한입 먹어봐요.', '제일 좋아하는 조합을 따라 해요.', '냄새부터 맡고 한 조각 작게 나눠요.']),
  (647, '연인이 지친 날, 화려한 외식과 편한 한 끼 중 어떻게 고를까요?', array['오늘 사람 많은 곳도 괜찮은지 물어요.', '편한 포장 메뉴 두 가지를 보내 봐요.', '고르고 싶은지 제가 정해도 될지 물어요.']),
  (653, '둘만의 비빔밥 양념을 만든다면 내가 먼저 권하고 싶은 조합은요?', array['된장에 매실청을 조금 풀어요.', '레몬간장에 구운 참깨를 섞어요.', '고추장에 잘 익은 토마토를 다져요.']),
  (655, '만남을 마치고 따뜻한 우유 한 잔을 건넨다면 뭘 넣어 주고 싶나요?', array['볶은 미숫가루를 천천히 풀어요.', '바닐라 한 방울과 꿀 조금이요.', '고구마를 으깨 넣고 잘 저어요.']),
  (665, '좋아하는 사람이 요리할 때 곁에서 구경하고 싶은 장면은 뭔가요?', array['오믈렛이 팬에서 포개지는 순간이요.', '식빵 반죽이 틀 밖까지 올라올 때요.', '팬에서 설탕이 호박색으로 변할 때요.']),
  (667, '둘이 장 본 재료가 남았다면 다음 만남으로 어떻게 이어 볼까요?', array['남은 바질로 다음엔 파스타를 권해요.', '사과 두 개는 소풍 가는 날을 위해 남겨요.', '반씩 가져가서 만든 요리 사진을 나눠요.']),
  (678, '서로 고른 재료를 넣어 데이트 샐러드를 완성한다면 내 몫은요?', array['저는 달달한 구운 단호박이요.', '아삭함을 줄 얇은 사과를 넣어요.', '고소한 병아리콩을 한 줌 더해요.']),
  (682, '상대를 저녁에 초대해 오븐에서 바로 내 주고 싶은 요리는요?', array['윗면이 갈라진 레몬 파운드케이크요.', '끝이 살짝 그을린 닭날개요.', '치즈가 보글거리는 감자 그라탱이요.']),
  (690, '나를 위해 요리하는 사람에게 몰래 남길 쪽지에는 뭘 쓸까요?', array['첫 한입은 요리한 사람 몫이에요.', '앞치마 주머니에 사탕 넣어 뒀어요.', '설거지는 내가 맡을 테니 앉아요.']),
  (696, '요리가 처음인 연인과 성공의 기쁨을 나눌 작은 간식은 무엇일까요?', array['바나나에 요구르트를 묻혀 얼려요.', '만두피에 치즈를 올려 구워요.', '잘게 부순 견과류를 꿀에 버무려요.']),
  (702, '마음에 든 사람과 식사 후 연락한다면 어떤 한마디로 다음을 열까요?', array['오늘 얘기한 국숫집 다음엔 같이 가요.', '덕분에 천천히 먹는 저녁이 참 좋았어요.', '아까 궁금해한 디저트, 다음에 맛볼래요?']),
  (706, '밤 산책 데이트를 마치기 전 반씩 나누고 싶은 따뜻한 간식은요?', array['고구마를 갈라 김이 오를 때 나눠요.', '호떡 속 꿀이 흐르기 전에 잘라요.', '단팥호빵을 손으로 반씩 가를래요.']),
  (714, '상대가 나의 음식 비유에 웃었어요. 어떤 표현을 더 들려줄까요?', array['누룽지 끝처럼 구수해요.', '첫 귤 한 쪽처럼 입안이 환해져요.', '감자를 푹 쪘을 때처럼 포슬포슬해요.']),
  (719, '둘이 소중하게 기억할 하루에 평소와 다른 밥을 짓는다면요?', array['껍질 깐 밤을 통으로 얹어요.', '초당옥수수 알을 듬뿍 섞어요.', '손질한 곤드레를 얹어 향을 입혀요.']),
  (725, '맛있는 접시가 나왔을 때 어떤 상대의 반응을 보면 나도 기쁜가요?', array['저랑 눈이 마주치자마자 웃을 때요.', '같이 먹길 잘했다고 말해 줄 때요.', '자기가 좋아하는 부분을 콕 짚어 줄 때요.']),
  (731, '첫 요리 데이트의 레시피 옆에 둘만의 메모를 남긴다면요?', array['오늘은 마늘을 두 쪽 더 넣었어요.', '다음에는 감자를 조금 더 두껍게요.', '처음 뒤집기는 실패, 두 번째는 성공!']);
